import{_ as s,c as e,b as a,o as t}from"./app-bavn2f3i.js";const p={};function l(c,n){return t(),e("div",null,[...n[0]||(n[0]=[a(`<h1 id="生命周期-⌚️" tabindex="-1"><a class="header-anchor" href="#生命周期-⌚️"><span>生命周期 ⌚️</span></a></h1><p>&gt; Last Format Time：7/30/2026 16:21:17</p><p>&gt; 适用范围：React 16.3+ 的新生命周期模型；以 React 19.2 官方文档为准。</p><hr><h2 id="先说结论" tabindex="-1"><a class="header-anchor" href="#先说结论"><span>先说结论</span></a></h2><ul><li>“生命周期方法”主要是<strong>类组件</strong>的概念。函数组件没有实例，也没有与每个类生命周期一一对应的方法。</li><li>函数组件的函数体属于<strong>渲染阶段</strong>；<code>useEffect</code>、<code>useLayoutEffect</code> 等 Effect 属于<strong>提交后的同步过程</strong>。Effect 应按“与外部系统同步”的思路理解，而不是机械地模拟 <code>componentDidMount</code> 等方法。</li><li>React 的一次工作可粗分为：<strong>触发更新 → 渲染（Render）→ 提交（Commit）→ 浏览器绘制（Paint）</strong>。</li><li>渲染阶段必须保持纯粹。并发渲染下，React 可能暂停、重启或放弃一次渲染，所以“函数体执行了”不等于“这次结果已提交到 DOM”。</li><li>类组件仍受支持，但 React 官方推荐新代码使用函数组件。</li></ul><hr><h2 id="一、完整调用顺序" tabindex="-1"><a class="header-anchor" href="#一、完整调用顺序"><span>一、完整调用顺序</span></a></h2><h3 id="挂载-mounting" tabindex="-1"><a class="header-anchor" href="#挂载-mounting"><span>挂载 Mounting</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">constructor</span>
<span class="line">  ↓</span>
<span class="line">static getDerivedStateFromProps</span>
<span class="line">  ↓</span>
<span class="line">render</span>
<span class="line">  ↓</span>
<span class="line">React 更新 DOM 和 ref</span>
<span class="line">  ↓</span>
<span class="line">componentDidMount</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>前三个处于渲染阶段，<code>componentDidMount</code> 处于提交阶段。</p><h3 id="更新-updating" tabindex="-1"><a class="header-anchor" href="#更新-updating"><span>更新 Updating</span></a></h3><p>更新可能由 <code>props</code>、<code>state</code> 或 <code>context</code> 变化触发：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">static getDerivedStateFromProps</span>
<span class="line">  ↓</span>
<span class="line">shouldComponentUpdate</span>
<span class="line">  ├─ false → 跳过本组件本次 render、getSnapshotBeforeUpdate、componentDidUpdate</span>
<span class="line">  └─ true</span>
<span class="line">       ↓</span>
<span class="line">     render</span>
<span class="line">       ↓</span>
<span class="line">     getSnapshotBeforeUpdate</span>
<span class="line">       ↓</span>
<span class="line">     React 更新 DOM 和 ref</span>
<span class="line">       ↓</span>
<span class="line">     componentDidUpdate</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意：<code>shouldComponentUpdate</code> 是性能优化提示，不适合用来保证业务逻辑正确性。调用 <code>forceUpdate()</code> 会跳过它。</p><h3 id="卸载-unmounting" tabindex="-1"><a class="header-anchor" href="#卸载-unmounting"><span>卸载 Unmounting</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">componentWillUnmount</span>
<span class="line">  ↓</span>
<span class="line">组件从页面移除</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="后代渲染出错-error-handling" tabindex="-1"><a class="header-anchor" href="#后代渲染出错-error-handling"><span>后代渲染出错 Error Handling</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">后代在渲染期间抛错</span>
<span class="line">  ↓</span>
<span class="line">static getDerivedStateFromError</span>
<span class="line">  ↓</span>
<span class="line">render 降级 UI</span>
<span class="line">  ↓</span>
<span class="line">提交降级 UI</span>
<span class="line">  ↓</span>
<span class="line">componentDidCatch</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="二、父子组件之间的执行顺序" tabindex="-1"><a class="header-anchor" href="#二、父子组件之间的执行顺序"><span>二、父子组件之间的执行顺序</span></a></h2><p>以下顺序以 <code>Parent → Child → Grandchild</code> 三层结构、未开启 Strict Mode、一次同步更新成功提交为前提。兄弟组件按 JSX 中的先后顺序逐棵深度优先处理。</p><h3 id="必须先区分两个阶段" tabindex="-1"><a class="header-anchor" href="#必须先区分两个阶段"><span>必须先区分两个阶段</span></a></h3><ul><li><strong>渲染阶段：父 → 子，深度优先。</strong> 父组件先计算出子组件元素，React 才知道接下来需要渲染哪些子组件。</li><li><strong>提交阶段：不能简单概括为永远“子 → 父”。</strong> 挂载完成回调通常是子 → 父；整棵子树真正删除时，卸载清理是父 → 子；更新时还会根据 Effect 类型和节点是否被删除产生不同顺序。</li></ul><p>渲染阶段可能被暂停、重试或放弃，提交阶段才表示这次结果真正生效。因此不能通过父子生命周期的先后顺序传递业务数据。</p><h3 id="类组件首次挂载" tabindex="-1"><a class="header-anchor" href="#类组件首次挂载"><span>类组件首次挂载</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Parent constructor</span>
<span class="line">Parent getDerivedStateFromProps</span>
<span class="line">Parent render</span>
<span class="line">  Child constructor</span>
<span class="line">  Child getDerivedStateFromProps</span>
<span class="line">  Child render</span>
<span class="line">    Grandchild constructor</span>
<span class="line">    Grandchild getDerivedStateFromProps</span>
<span class="line">    Grandchild render</span>
<span class="line">    Grandchild componentDidMount</span>
<span class="line">  Child componentDidMount</span>
<span class="line">Parent componentDidMount</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>可记为：</p><ul><li>渲染阶段的 <code>constructor → getDerivedStateFromProps → render</code>：<strong>父 → 子</strong>；</li><li>提交阶段的 <code>componentDidMount</code>：<strong>子 → 父</strong>。</li></ul><p>若有两个兄弟 <code>ChildA</code>、<code>ChildB</code>，常见顺序是先完成 A 的整棵渲染，再完成 B 的整棵渲染；挂载提交顺序为 <code>ChildA componentDidMount → ChildB componentDidMount → Parent componentDidMount</code>。</p><h3 id="类组件父子同时更新" tabindex="-1"><a class="header-anchor" href="#类组件父子同时更新"><span>类组件父子同时更新</span></a></h3><p>假设父组件更新并向子组件传入新 props：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Parent getDerivedStateFromProps</span>
<span class="line">Parent shouldComponentUpdate</span>
<span class="line">Parent render</span>
<span class="line">  Child getDerivedStateFromProps</span>
<span class="line">  Child shouldComponentUpdate</span>
<span class="line">  Child render</span>
<span class="line">    Grandchild ...</span>
<span class="line">    Grandchild getSnapshotBeforeUpdate</span>
<span class="line">  Child getSnapshotBeforeUpdate</span>
<span class="line">Parent getSnapshotBeforeUpdate</span>
<span class="line"></span>
<span class="line">React 修改 DOM</span>
<span class="line"></span>
<span class="line">    Grandchild componentDidUpdate</span>
<span class="line">  Child componentDidUpdate</span>
<span class="line">Parent componentDidUpdate</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>即：</p><ul><li>更新渲染阶段：<strong>父 → 子</strong>；</li><li><code>getSnapshotBeforeUpdate</code>：<strong>子 → 父</strong>；</li><li><code>componentDidUpdate</code>：<strong>子 → 父</strong>。</li></ul><p>如果 <code>Parent.shouldComponentUpdate()</code> 返回 <code>false</code>，由这次父级更新引起的父组件后续渲染和子树遍历都会跳过；但子组件仍可能因为自己的 state、context 或其他更新源而独立更新。</p><h3 id="类组件卸载" tabindex="-1"><a class="header-anchor" href="#类组件卸载"><span>类组件卸载</span></a></h3><h5 id="父组件连同整棵子树一起卸载" tabindex="-1"><a class="header-anchor" href="#父组件连同整棵子树一起卸载"><span>父组件连同整棵子树一起卸载</span></a></h5><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Parent componentWillUnmount</span>
<span class="line">  Child componentWillUnmount</span>
<span class="line">    Grandchild componentWillUnmount</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>是<strong>父 → 子</strong>，不要和挂载时的 <code>componentDidMount</code> 顺序混淆。</p><h5 id="父组件更新时只移除-child" tabindex="-1"><a class="header-anchor" href="#父组件更新时只移除-child"><span>父组件更新时只移除 Child</span></a></h5><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Parent render</span>
<span class="line">Parent getSnapshotBeforeUpdate   // 如果实现了</span>
<span class="line">  Child componentWillUnmount</span>
<span class="line">Parent componentDidUpdate</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Child 的后代也会在 Child 之后继续按父 → 子执行 <code>componentWillUnmount</code>。</p><h3 id="函数组件首次挂载" tabindex="-1"><a class="header-anchor" href="#函数组件首次挂载"><span>函数组件首次挂载</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Parent 函数体</span>
<span class="line">  Child 函数体</span>
<span class="line">    Grandchild 函数体</span>
<span class="line"></span>
<span class="line">    Grandchild useInsertionEffect setup</span>
<span class="line">  Child useInsertionEffect setup</span>
<span class="line">Parent useInsertionEffect setup</span>
<span class="line"></span>
<span class="line">    Grandchild useLayoutEffect setup</span>
<span class="line">  Child useLayoutEffect setup</span>
<span class="line">Parent useLayoutEffect setup</span>
<span class="line"></span>
<span class="line">浏览器通常完成绘制</span>
<span class="line"></span>
<span class="line">    Grandchild useEffect setup</span>
<span class="line">  Child useEffect setup</span>
<span class="line">Parent useEffect setup</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>可记为：</p><ul><li>函数组件执行（渲染阶段）：<strong>父 → 子</strong>；</li><li><code>useInsertionEffect</code>、<code>useLayoutEffect</code>、<code>useEffect</code> 的首次 setup：<strong>子 → 父</strong>；</li><li><code>useLayoutEffect</code> 在绘制前同步执行；<code>useEffect</code> 通常在绘制后执行。</li></ul><h3 id="函数组件更新" tabindex="-1"><a class="header-anchor" href="#函数组件更新"><span>函数组件更新</span></a></h3><p>父子共同重新渲染时，函数体仍是父 → 子。对于每一个依赖发生变化的 Effect，React 保证：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">该 Effect 上一轮 cleanup（旧 props/state）</span>
<span class="line">  ↓</span>
<span class="line">该 Effect 新一轮 setup（新 props/state）</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>React DOM 19.2.x 中，多层组件常见的 <code>useEffect</code> 更新顺序是：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Child useEffect cleanup</span>
<span class="line">Parent useEffect cleanup</span>
<span class="line">Child useEffect setup</span>
<span class="line">Parent useEffect setup</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>但只应把“<strong>同一个 Effect 的 cleanup 一定先于它的下一次 setup</strong>”当作业务语义。不要让父 Effect 必须等待子 Effect，或让子 Effect 必须依赖父 Effect 已执行；React 官方没有把跨组件 Effect 的完整遍历顺序定义为组件通信契约。</p><p><code>useInsertionEffect</code> 和 <code>useLayoutEffect</code> 在更新提交中的清理、建立时机与 <code>useEffect</code> 不完全相同，多个组件之间还可能交错。业务代码应依赖各自的 setup/cleanup 对称性，而不是背诵一条统一顺序。</p><h3 id="函数组件卸载" tabindex="-1"><a class="header-anchor" href="#函数组件卸载"><span>函数组件卸载</span></a></h3><p>整棵子树真正从 React 树中删除时，React DOM 19.2.x 的常见顺序是父 → 子：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Parent useLayoutEffect cleanup</span>
<span class="line">  Child useLayoutEffect cleanup</span>
<span class="line">    Grandchild useLayoutEffect cleanup</span>
<span class="line"></span>
<span class="line">Parent useEffect cleanup</span>
<span class="line">  Child useEffect cleanup</span>
<span class="line">    Grandchild useEffect cleanup</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果父组件更新时只删除 Child，则 Child 子树的布局 Effect 在提交删除时清理，被动 <code>useEffect</code> 的 cleanup 随后在被动 Effect 阶段执行。</p><p>&gt; 面试中经常出现“Effect cleanup 永远子 → 父”的错误结论。依赖变化时的重新同步与节点真正卸载是两条不同路径；最稳妥的回答是先说明场景，再给出当前 React DOM 的可观察顺序，并强调跨组件顺序不应用作业务契约。</p><h3 id="strict-mode-对日志顺序的影响" tabindex="-1"><a class="header-anchor" href="#strict-mode-对日志顺序的影响"><span>Strict Mode 对日志顺序的影响</span></a></h3><p>开发环境启用 <code>&amp;lt;StrictMode&amp;gt;</code> 后，组件函数、部分纯生命周期以及 Effect setup/cleanup 会额外执行检查。因此控制台可能看到重复的父子渲染，以及挂载后的 setup → cleanup → setup。生产环境没有这轮额外检查；分析基础顺序时应先关闭 Strict Mode，排除检查日志的干扰。</p><h3 id="父子组件顺序速记" tabindex="-1"><a class="header-anchor" href="#父子组件顺序速记"><span>父子组件顺序速记</span></a></h3><table><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">方向</th></tr></thead><tbody><tr><td style="text-align:left;">类组件/函数组件的渲染阶段</td><td style="text-align:left;">父 → 子，深度优先</td></tr><tr><td style="text-align:left;"><code>componentDidMount</code></td><td style="text-align:left;">子 → 父</td></tr><tr><td style="text-align:left;"><code>getSnapshotBeforeUpdate</code></td><td style="text-align:left;">子 → 父</td></tr><tr><td style="text-align:left;"><code>componentDidUpdate</code></td><td style="text-align:left;">子 → 父</td></tr><tr><td style="text-align:left;">整棵类组件子树的 <code>componentWillUnmount</code></td><td style="text-align:left;">父 → 子</td></tr><tr><td style="text-align:left;">函数组件首次 Effect setup</td><td style="text-align:left;">子 → 父</td></tr><tr><td style="text-align:left;">同一个 Effect 依赖变化</td><td style="text-align:left;">旧 cleanup → 新 setup</td></tr><tr><td style="text-align:left;">整棵函数组件子树真正卸载时的 Effect cleanup</td><td style="text-align:left;">React DOM 19.2.x 中通常父 → 子；不要作为跨组件通信契约</td></tr></tbody></table><hr><h2 id="三、类组件全部生命周期-api" tabindex="-1"><a class="header-anchor" href="#三、类组件全部生命周期-api"><span>三、类组件全部生命周期 API</span></a></h2><p>&gt; <code>render</code> 是类组件唯一必需的方法，其余均可选。<code>constructor</code> 严格说是 JavaScript 构造器，但面试中通常与生命周期一起讨论。</p><h3 id="constructor-props-实例初始化" tabindex="-1"><a class="header-anchor" href="#constructor-props-实例初始化"><span><code>constructor(props)</code>：实例初始化</span></a></h3><p><strong>时机：</strong> 挂载前调用。</p><h3 id="用途" tabindex="-1"><a class="header-anchor" href="#用途"><span>用途</span></a></h3><ul><li>初始化 <code>state</code>；</li><li>绑定实例方法的 <code>this</code>。使用类字段和箭头函数后通常不再需要它。</li></ul><h3 id="约束" tabindex="-1"><a class="header-anchor" href="#约束"><span>约束</span></a></h3><ul><li>其他语句之前先调用 <code>super(props)</code>；</li><li>除类字段初始化外，只在这里直接给 <code>this.state</code> 赋值；不能在这里调用 <code>setState</code>；</li><li>必须纯粹，不要请求数据、订阅或操作 DOM；</li><li>服务端渲染会执行 <code>constructor</code> 和 <code>render</code>，但不会执行挂载、更新、卸载相关的提交阶段生命周期。</li></ul><div class="language-jsx line-numbers-mode" data-highlighter="prismjs" data-ext="jsx"><pre><code class="language-jsx"><span class="line"><span class="token keyword">class</span> <span class="token class-name">Counter</span> <span class="token keyword">extends</span> <span class="token class-name">React<span class="token punctuation">.</span>Component</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token parameter">props</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">super</span><span class="token punctuation">(</span>props<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span>state <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">count</span><span class="token operator">:</span> <span class="token number">0</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span>handleClick <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">handleClick</span><span class="token punctuation">.</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="static-getderivedstatefromprops-props-state-由-props-派生-state" tabindex="-1"><a class="header-anchor" href="#static-getderivedstatefromprops-props-state-由-props-派生-state"><span><code>static getDerivedStateFromProps(props, state)</code>：由 props 派生 state</span></a></h3><p><strong>时机：</strong> 初次挂载和每次更新时，在 <code>render</code> 之前调用。</p><p><strong>返回值：</strong> 返回 state 更新对象，或返回 <code>null</code> 表示不更新。</p><h3 id="约束-1" tabindex="-1"><a class="header-anchor" href="#约束-1"><span>约束</span></a></h3><ul><li>必须是静态、纯函数，不能访问组件实例 <code>this</code>，不能执行副作用；</li><li>每次父组件重新渲染时都可能调用，不只在 props 变化时调用；</li><li>这是少见场景。滥用会产生“双数据源”和 state 与 props 不同步问题。</li></ul><p>更常见的替代方案：</p><ul><li>仅计算派生值：直接在渲染期间计算，昂贵计算再考虑 <code>useMemo</code>；</li><li>props 变化后执行副作用：<code>componentDidUpdate</code> / <code>useEffect</code>；</li><li>props 变化时重置全部内部状态：通过变化的 <code>key</code> 让 React 重新挂载组件；</li><li>需要保留上一轮 props：优先重新设计数据结构，确有必要再在渲染期间调整 state。</li></ul><div class="language-jsx line-numbers-mode" data-highlighter="prismjs" data-ext="jsx"><pre><code class="language-jsx"><span class="line"><span class="token keyword">static</span> <span class="token function">getDerivedStateFromProps</span><span class="token punctuation">(</span><span class="token parameter">props<span class="token punctuation">,</span> state</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>props<span class="token punctuation">.</span>userId <span class="token operator">!==</span> state<span class="token punctuation">.</span>prevUserId<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">prevUserId</span><span class="token operator">:</span> props<span class="token punctuation">.</span>userId<span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">selectedItem</span><span class="token operator">:</span> <span class="token keyword">null</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="render-计算-ui" tabindex="-1"><a class="header-anchor" href="#render-计算-ui"><span><code>render()</code>：计算 UI</span></a></h3><p><strong>时机：</strong> 挂载和更新的渲染阶段。</p><p><strong>作用：</strong> 根据 <code>props</code>、<code>state</code>、<code>context</code> 返回 React 节点。</p><h3 id="约束-2" tabindex="-1"><a class="header-anchor" href="#约束-2"><span>约束</span></a></h3><ul><li>必须是纯函数：相同输入应得到相同输出；</li><li>不能订阅、请求、调用 <code>setState</code> 或读写 DOM；</li><li>React 可以多次调用或放弃某次渲染，只有提交完成才代表 UI 生效；</li><li><code>shouldComponentUpdate</code> 返回 <code>false</code> 时，本次更新会跳过 <code>render</code>。</li></ul><p>可返回 React 元素、字符串、数字、Portal、节点数组，以及空节点 <code>null</code>、<code>undefined</code>、<code>true</code>、<code>false</code>。</p><h3 id="componentdidmount-挂载提交完成" tabindex="-1"><a class="header-anchor" href="#componentdidmount-挂载提交完成"><span><code>componentDidMount()</code>：挂载提交完成</span></a></h3><p><strong>时机：</strong> 组件加入屏幕后调用一次（每次实际挂载一次；不是整个应用全局只执行一次）。</p><p><strong>用途：</strong> 建立订阅、连接外部系统、操作 DOM。数据请求也能放在这里，但现代框架的数据加载或客户端缓存方案通常更合适。</p><h3 id="约束-3" tabindex="-1"><a class="header-anchor" href="#约束-3"><span>约束</span></a></h3><ul><li>在这里读取了会变化的 props/state，通常还要在 <code>componentDidUpdate</code> 处理变化；</li><li>建立的订阅、定时器、连接必须在 <code>componentWillUnmount</code> 对称清理；</li><li>可调用 <code>setState</code>，但会额外渲染一次，应只用于测量 DOM 等少数场景。</li></ul><h3 id="shouldcomponentupdate-nextprops-nextstate-nextcontext-跳过不必要更新" tabindex="-1"><a class="header-anchor" href="#shouldcomponentupdate-nextprops-nextstate-nextcontext-跳过不必要更新"><span><code>shouldComponentUpdate(nextProps, nextState, nextContext)</code>：跳过不必要更新</span></a></h3><p><strong>时机：</strong> 收到新 props/state 后、渲染前；初次挂载和 <code>forceUpdate()</code> 时不调用。</p><p><strong>返回值：</strong> 默认语义相当于返回 <code>true</code>；返回 <code>false</code> 会跳过本组件本次后续渲染流程。</p><h3 id="约束-4" tabindex="-1"><a class="header-anchor" href="#约束-4"><span>约束</span></a></h3><ul><li>必须纯粹，不能产生副作用或调用 <code>setState</code>；</li><li>不建议手写深比较或 <code>JSON.stringify</code>，可能比渲染更慢；</li><li>类组件通常优先继承 <code>PureComponent</code>；函数组件对应 <code>memo</code>；</li><li>不能把返回 <code>false</code> 当成阻止渲染的业务保证，React 官方只把它定位为性能优化。</li></ul><p><code>PureComponent</code> 会对 props 和 state 的每个字段做浅比较。因此不可直接修改原对象后继续复用同一引用。</p><h3 id="getsnapshotbeforeupdate-prevprops-prevstate-提交-dom-前取快照" tabindex="-1"><a class="header-anchor" href="#getsnapshotbeforeupdate-prevprops-prevstate-提交-dom-前取快照"><span><code>getSnapshotBeforeUpdate(prevProps, prevState)</code>：提交 DOM 前取快照</span></a></h3><p><strong>时机：</strong> <code>render</code> 之后、React 修改 DOM 之前。</p><p><strong>返回值：</strong> 任意快照值或 <code>null</code>；该值会成为 <code>componentDidUpdate</code> 的第三个参数。</p><p><strong>用途：</strong> 在 DOM 改变前读取滚动位置等信息，再在 DOM 改变后恢复。</p><h3 id="约束-5" tabindex="-1"><a class="header-anchor" href="#约束-5"><span>约束</span></a></h3><ul><li><code>shouldComponentUpdate</code> 返回 <code>false</code> 时不会调用；</li><li>函数组件目前没有精确等价 Hook；</li><li>不要在 <code>render</code> 或 <code>UNSAFE_componentWillUpdate</code> 中读取这类 DOM 快照，因为并发渲染下渲染与提交之间可能存在时间间隔。</li></ul><div class="language-jsx line-numbers-mode" data-highlighter="prismjs" data-ext="jsx"><pre><code class="language-jsx"><span class="line"><span class="token function">getSnapshotBeforeUpdate</span><span class="token punctuation">(</span><span class="token parameter">prevProps</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>prevProps<span class="token punctuation">.</span>items<span class="token punctuation">.</span>length <span class="token operator">&lt;</span> <span class="token keyword">this</span><span class="token punctuation">.</span>props<span class="token punctuation">.</span>items<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> list <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span>listRef<span class="token punctuation">.</span>current<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> list<span class="token punctuation">.</span>scrollHeight <span class="token operator">-</span> list<span class="token punctuation">.</span>scrollTop<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token function">componentDidUpdate</span><span class="token punctuation">(</span><span class="token parameter">prevProps<span class="token punctuation">,</span> prevState<span class="token punctuation">,</span> snapshot</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>snapshot <span class="token operator">!==</span> <span class="token keyword">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> list <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span>listRef<span class="token punctuation">.</span>current<span class="token punctuation">;</span></span>
<span class="line">    list<span class="token punctuation">.</span>scrollTop <span class="token operator">=</span> list<span class="token punctuation">.</span>scrollHeight <span class="token operator">-</span> snapshot<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="componentdidupdate-prevprops-prevstate-snapshot-更新提交完成" tabindex="-1"><a class="header-anchor" href="#componentdidupdate-prevprops-prevstate-snapshot-更新提交完成"><span><code>componentDidUpdate(prevProps, prevState, snapshot)</code>：更新提交完成</span></a></h3><p><strong>时机：</strong> 更新后的 DOM 已提交时调用；初次挂载不调用。</p><h3 id="参数" tabindex="-1"><a class="header-anchor" href="#参数"><span>参数</span></a></h3><ul><li><code>prevProps</code>：更新前 props；</li><li><code>prevState</code>：更新前 state；</li><li><code>snapshot</code>：<code>getSnapshotBeforeUpdate</code> 的返回值，未实现该方法时为 <code>undefined</code>。</li></ul><h3 id="约束-6" tabindex="-1"><a class="header-anchor" href="#约束-6"><span>约束</span></a></h3><ul><li><code>shouldComponentUpdate</code> 返回 <code>false</code> 时不会调用；</li><li>调用 <code>setState</code> 前必须做前后值判断，否则容易无限更新；</li><li>常与 <code>componentDidMount</code>、<code>componentWillUnmount</code> 组成一套对称的同步逻辑。</li></ul><div class="language-jsx line-numbers-mode" data-highlighter="prismjs" data-ext="jsx"><pre><code class="language-jsx"><span class="line"><span class="token function">componentDidUpdate</span><span class="token punctuation">(</span><span class="token parameter">prevProps</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>prevProps<span class="token punctuation">.</span>roomId <span class="token operator">!==</span> <span class="token keyword">this</span><span class="token punctuation">.</span>props<span class="token punctuation">.</span>roomId<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">disconnect</span><span class="token punctuation">(</span>prevProps<span class="token punctuation">.</span>roomId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">connect</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>props<span class="token punctuation">.</span>roomId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="componentwillunmount-卸载前清理" tabindex="-1"><a class="header-anchor" href="#componentwillunmount-卸载前清理"><span><code>componentWillUnmount()</code>：卸载前清理</span></a></h3><p><strong>时机：</strong> 组件从屏幕移除前调用。</p><p><strong>用途：</strong> 取消订阅、清除定时器、断开连接、取消仍可取消的请求等。</p><h3 id="约束-7" tabindex="-1"><a class="header-anchor" href="#约束-7"><span>约束</span></a></h3><ul><li>清理逻辑应与 <code>componentDidMount</code> 的建立逻辑对称；</li><li>不应调用 <code>setState</code>，组件不会再次渲染；</li><li>不能假设它会在浏览器崩溃、进程结束等非正常退出场景执行。</li></ul><h3 id="static-getderivedstatefromerror-error-错误降级-ui" tabindex="-1"><a class="header-anchor" href="#static-getderivedstatefromerror-error-错误降级-ui"><span><code>static getDerivedStateFromError(error)</code>：错误降级 UI</span></a></h3><p><strong>时机：</strong> 后代组件在渲染期间抛错后调用。</p><p><strong>返回值：</strong> state 更新对象，用于下一次渲染显示降级 UI。</p><p><strong>约束：</strong> 必须纯粹，不在这里上报错误；日志上报放到 <code>componentDidCatch</code>。</p><h3 id="componentdidcatch-error-info-记录后代错误" tabindex="-1"><a class="header-anchor" href="#componentdidcatch-error-info-记录后代错误"><span><code>componentDidCatch(error, info)</code>：记录后代错误</span></a></h3><p><strong>时机：</strong> 后代渲染错误被捕获、降级 UI 提交后调用。</p><p><strong>参数：</strong> <code>error</code> 是抛出的值；<code>info.componentStack</code> 是组件栈。</p><p>定义 <code>getDerivedStateFromError</code> 和/或 <code>componentDidCatch</code> 的组件称为 <strong>Error Boundary（错误边界）</strong>。</p><p>错误边界能捕获后代在以下位置抛出的错误：</p><ul><li>渲染期间；</li><li>构造器；</li><li>生命周期方法。</li></ul><p>它通常不能捕获：</p><ul><li>自身内部抛出的错误；</li><li>事件处理函数中的错误（应用普通 <code>try...catch</code>）；</li><li><code>setTimeout</code> 等异步回调中的错误；</li><li>服务端渲染中的错误。</li></ul><p>函数组件目前没有内置的、与 <code>componentDidCatch</code> 完全等价的 Hook，通常保留一个类错误边界或使用封装库。</p><div class="language-jsx line-numbers-mode" data-highlighter="prismjs" data-ext="jsx"><pre><code class="language-jsx"><span class="line"><span class="token keyword">class</span> <span class="token class-name">ErrorBoundary</span> <span class="token keyword">extends</span> <span class="token class-name">React<span class="token punctuation">.</span>Component</span> <span class="token punctuation">{</span></span>
<span class="line">  state <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">hasError</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">static</span> <span class="token function">getDerivedStateFromError</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">{</span> <span class="token literal-property property">hasError</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token function">componentDidCatch</span><span class="token punctuation">(</span><span class="token parameter">error<span class="token punctuation">,</span> info</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">reportError</span><span class="token punctuation">(</span>error<span class="token punctuation">,</span> info<span class="token punctuation">.</span>componentStack<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>state<span class="token punctuation">.</span>hasError</span>
<span class="line">      <span class="token operator">?</span> <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token plain-text">页面出现异常</span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">      <span class="token operator">:</span> <span class="token keyword">this</span><span class="token punctuation">.</span>props<span class="token punctuation">.</span>children<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="四、不安全-已废弃生命周期" tabindex="-1"><a class="header-anchor" href="#四、不安全-已废弃生命周期"><span>四、不安全/已废弃生命周期</span></a></h2><p>以下旧名称已经废弃：</p><ul><li><code>componentWillMount</code> → <code>UNSAFE_componentWillMount</code></li><li><code>componentWillReceiveProps</code> → <code>UNSAFE_componentWillReceiveProps</code></li><li><code>componentWillUpdate</code> → <code>UNSAFE_componentWillUpdate</code></li></ul><p>它们在异步/并发渲染中不安全：渲染工作可能被重复、暂停或放弃，因此不能依赖它们“只执行一次”，也不能在其中执行副作用。新代码不要使用。</p><h3 id="unsafe-componentwillmount" tabindex="-1"><a class="header-anchor" href="#unsafe-componentwillmount"><span><code>UNSAFE_componentWillMount()</code></span></a></h3><ul><li>挂载前调用，历史上位于 <code>constructor</code> 与 <code>render</code> 之间；</li><li>初始化 state 放到字段或 <code>constructor</code>；副作用放到 <code>componentDidMount</code>；</li><li>服务端渲染时它是除 <code>constructor</code>、<code>render</code> 外还会执行的旧生命周期，因此更容易导致服务端/客户端行为不一致。</li></ul><h3 id="unsafe-componentwillreceiveprops-nextprops-nextcontext" tabindex="-1"><a class="header-anchor" href="#unsafe-componentwillreceiveprops-nextprops-nextcontext"><span><code>UNSAFE_componentWillReceiveProps(nextProps, nextContext)</code></span></a></h3><ul><li>已挂载组件接收父级新 props 时调用；初次挂载不调用；</li><li>父组件重新渲染即可触发，不能以“值一定改变”为前提；</li><li>根据 props 计算数据应在渲染期间完成；需要重置 state 时优先使用受控组件或 <code>key</code>。</li></ul><h3 id="unsafe-componentwillupdate-nextprops-nextstate" tabindex="-1"><a class="header-anchor" href="#unsafe-componentwillupdate-nextprops-nextstate"><span><code>UNSAFE_componentWillUpdate(nextProps, nextState)</code></span></a></h3><ul><li>更新渲染前调用，初次挂载不调用；</li><li>不能调用 <code>setState</code>；不能可靠地在此读取更新前 DOM；</li><li>DOM 快照应使用 <code>getSnapshotBeforeUpdate</code>，提交后的副作用使用 <code>componentDidUpdate</code>。</li></ul><p>如果类中实现了 <code>static getDerivedStateFromProps</code> 或 <code>getSnapshotBeforeUpdate</code>，React 不会调用这些 <code>UNSAFE_</code> 旧生命周期。</p><hr><h2 id="五、函数组件如何正确理解-生命周期" tabindex="-1"><a class="header-anchor" href="#五、函数组件如何正确理解-生命周期"><span>五、函数组件如何正确理解“生命周期”</span></a></h2><h3 id="函数组件函数体-对应渲染阶段-不等于-render-的一次提交" tabindex="-1"><a class="header-anchor" href="#函数组件函数体-对应渲染阶段-不等于-render-的一次提交"><span>函数组件函数体：对应渲染阶段，不等于 <code>render()</code> 的一次提交</span></a></h3><div class="language-jsx line-numbers-mode" data-highlighter="prismjs" data-ext="jsx"><pre><code class="language-jsx"><span class="line"><span class="token keyword">function</span> <span class="token function">Profile</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> user <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> <span class="token punctuation">[</span>tab<span class="token punctuation">,</span> setTab<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">useState</span><span class="token punctuation">(</span><span class="token string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> title <span class="token operator">=</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>user<span class="token punctuation">.</span>name<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> - </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>tab<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">{</span>title<span class="token punctuation">}</span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>函数体应保持纯粹。不要在其中请求、订阅、写 DOM 或注册定时器。</p><h3 id="初始化状态-usestate-usereducer" tabindex="-1"><a class="header-anchor" href="#初始化状态-usestate-usereducer"><span>初始化状态：<code>useState</code> / <code>useReducer</code></span></a></h3><p>函数组件没有 <code>constructor</code> 的精确对应物。昂贵的初始计算使用惰性初始化函数：</p><div class="language-jsx line-numbers-mode" data-highlighter="prismjs" data-ext="jsx"><pre><code class="language-jsx"><span class="line"><span class="token keyword">const</span> <span class="token punctuation">[</span>state<span class="token punctuation">,</span> setState<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">useState</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">createInitialState</span><span class="token punctuation">(</span>props<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>初始化函数也必须纯粹；Strict Mode 开发环境可能调用两次来检查纯度。</p><h3 id="useeffect-与外部系统同步" tabindex="-1"><a class="header-anchor" href="#useeffect-与外部系统同步"><span><code>useEffect</code>：与外部系统同步</span></a></h3><div class="language-jsx line-numbers-mode" data-highlighter="prismjs" data-ext="jsx"><pre><code class="language-jsx"><span class="line"><span class="token function">useEffect</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> connection <span class="token operator">=</span> <span class="token function">createConnection</span><span class="token punctuation">(</span>serverUrl<span class="token punctuation">,</span> roomId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  connection<span class="token punctuation">.</span><span class="token function">connect</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> connection<span class="token punctuation">.</span><span class="token function">disconnect</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>serverUrl<span class="token punctuation">,</span> roomId<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对于很多场景，一个 Effect 的 setup/cleanup 可以覆盖类组件中分散在以下三处的逻辑：</p><ul><li><code>componentDidMount</code>：建立连接；</li><li><code>componentDidUpdate</code>：依赖改变时先清理旧连接，再建立新连接；</li><li><code>componentWillUnmount</code>：清理最后的连接。</li></ul><p>但它们并不完全等价：</p><ul><li><code>useEffect</code> 在初次提交后也会执行，不能直接表示“只在更新后、不在挂载后”；</li><li>依赖变化时，React 会先以旧值执行 cleanup，再以新值执行 setup；</li><li>卸载时执行最后一次 cleanup；</li><li><code>useEffect</code> 通常允许浏览器先绘制，视觉测量/同步布局应考虑 <code>useLayoutEffect</code>；</li><li>Effect 只在客户端执行，服务端渲染不执行。</li></ul><h3 id="uselayouteffect-绘制前同步布局" tabindex="-1"><a class="header-anchor" href="#uselayouteffect-绘制前同步布局"><span><code>useLayoutEffect</code>：绘制前同步布局</span></a></h3><p>执行在 DOM 提交后、浏览器重新绘制前，适合测量 DOM 并立刻修正布局。它会阻塞绘制，应优先使用 <code>useEffect</code>，仅在避免闪烁或同步测量时使用。</p><div class="language-jsx line-numbers-mode" data-highlighter="prismjs" data-ext="jsx"><pre><code class="language-jsx"><span class="line"><span class="token function">useLayoutEffect</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> rect <span class="token operator">=</span> ref<span class="token punctuation">.</span>current<span class="token punctuation">.</span><span class="token function">getBoundingClientRect</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token function">setHeight</span><span class="token punctuation">(</span>rect<span class="token punctuation">.</span>height<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>它比 <code>useEffect</code> 更接近类组件 <code>componentDidMount</code> / <code>componentDidUpdate</code> 的提交时机，但仍不是 <code>getSnapshotBeforeUpdate</code> 的替代品。</p><h3 id="useinsertioneffect-css-in-js-库专用" tabindex="-1"><a class="header-anchor" href="#useinsertioneffect-css-in-js-库专用"><span><code>useInsertionEffect</code>：CSS-in-JS 库专用</span></a></h3><p>它会在其他布局 Effect 运行前插入动态样式。普通业务组件不应使用；其主要受众是运行时 CSS-in-JS 库作者。此时 ref 还未附加，也不能在其中更新 state。</p><h3 id="性能优化-memo、usememo、usecallback" tabindex="-1"><a class="header-anchor" href="#性能优化-memo、usememo、usecallback"><span>性能优化：<code>memo</code>、<code>useMemo</code>、<code>useCallback</code></span></a></h3><table><thead><tr><th style="text-align:left;">类组件</th><th style="text-align:left;">函数组件</th><th style="text-align:left;">准确含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>PureComponent</code> / <code>shouldComponentUpdate</code></td><td style="text-align:left;"><code>memo</code></td><td style="text-align:left;">在 props 未变化时尝试跳过组件重新渲染</td></tr><tr><td style="text-align:left;">在实例字段中缓存结果</td><td style="text-align:left;"><code>useMemo</code></td><td style="text-align:left;">缓存一次计算结果</td></tr><tr><td style="text-align:left;">稳定的实例方法</td><td style="text-align:left;"><code>useCallback</code></td><td style="text-align:left;">缓存函数引用</td></tr></tbody></table><p>它们都是性能优化工具，不是保证语义正确的生命周期机制。<code>useMemo</code>、<code>useCallback</code> 也不能用来承载副作用。</p><h3 id="没有精确-hook-对应物的生命周期" tabindex="-1"><a class="header-anchor" href="#没有精确-hook-对应物的生命周期"><span>没有精确 Hook 对应物的生命周期</span></a></h3><table><thead><tr><th style="text-align:left;">类 API</th><th style="text-align:left;">函数组件结论</th></tr></thead><tbody><tr><td style="text-align:left;"><code>getSnapshotBeforeUpdate</code></td><td style="text-align:left;">目前没有精确等价 Hook，必要时保留类组件</td></tr><tr><td style="text-align:left;"><code>componentDidCatch</code> / 错误边界</td><td style="text-align:left;">目前没有内置函数组件错误边界 Hook，使用类边界或封装库</td></tr><tr><td style="text-align:left;"><code>getDerivedStateFromProps</code></td><td style="text-align:left;">通常在渲染期间直接计算、使用 <code>key</code> 重置状态或重新设计状态结构</td></tr><tr><td style="text-align:left;">仅更新时运行的 <code>componentDidUpdate</code></td><td style="text-align:left;"><code>useEffect</code> 默认挂载后也运行；可用 ref 跳过首轮，但先确认需求是否合理</td></tr></tbody></table><hr><h2 id="六、effect-依赖项完整规则" tabindex="-1"><a class="header-anchor" href="#六、effect-依赖项完整规则"><span>六、Effect 依赖项完整规则</span></a></h2><table><thead><tr><th style="text-align:left;">写法</th><th style="text-align:left;">setup 执行时机</th><th style="text-align:left;">cleanup 执行时机</th></tr></thead><tbody><tr><td style="text-align:left;">省略第二个参数</td><td style="text-align:left;">每次提交后</td><td style="text-align:left;">下一次 setup 前；卸载时</td></tr><tr><td style="text-align:left;">空数组 <code>[]</code></td><td style="text-align:left;">该次挂载提交后</td><td style="text-align:left;">卸载时</td></tr><tr><td style="text-align:left;"><code>[dep1, dep2]</code></td><td style="text-align:left;">挂载提交后；任一依赖与上次不同时</td><td style="text-align:left;">依赖变化后的新 setup 前；卸载时</td></tr></tbody></table><p>更严谨地说，<code>[]</code> 表示“这个 Effect 没有响应式依赖”，不是“整个应用生命周期中绝对只执行一次”。组件因 <code>key</code> 变化、条件渲染或路由切换而重新挂载时会再次执行；Strict Mode 开发环境还会额外执行一次 setup → cleanup → setup 检查。</p><h3 id="依赖是如何比较的" tabindex="-1"><a class="header-anchor" href="#依赖是如何比较的"><span>依赖是如何比较的</span></a></h3><ul><li>React 使用 <code>Object.is</code> <strong>逐项比较</strong>新旧依赖，不是递归深比较；</li><li>依赖列表必须写成固定长度的内联数组，如 <code>[a, b]</code>；</li><li>props、state，以及组件函数体内声明并被 Effect 读取的变量和函数，都属于响应式值，应列入依赖；</li><li>不要为了控制执行次数故意漏依赖，应启用 <code>eslint-plugin-react-hooks</code> 的 <code>exhaustive-deps</code> 规则。</li></ul><h3 id="对象和函数依赖" tabindex="-1"><a class="header-anchor" href="#对象和函数依赖"><span>对象和函数依赖</span></a></h3><p>每次渲染新建的对象、数组、函数具有新引用，<code>Object.is</code> 比较会判定其变化。优先按以下顺序处理：</p><ol><li>删除本来就不需要的 Effect；</li><li>把对象或函数移到 Effect 内部创建；</li><li>依赖真正使用的基础类型字段；</li><li>确有共享稳定引用的需要时，再用 <code>useMemo</code> / <code>useCallback</code>。</li></ol><p>不要为了“让依赖稳定”而无条件缓存一切。</p><h3 id="闭包与旧值" tabindex="-1"><a class="header-anchor" href="#闭包与旧值"><span>闭包与旧值</span></a></h3><p>每次渲染都有自己的 props、state 和闭包。Effect 捕获的是创建它的那次渲染中的值：</p><div class="language-jsx line-numbers-mode" data-highlighter="prismjs" data-ext="jsx"><pre><code class="language-jsx"><span class="line"><span class="token comment">// 错误：count 被固定为首次渲染的值</span></span>
<span class="line"><span class="token function">useEffect</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> id <span class="token operator">=</span> <span class="token function">setInterval</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">setCount</span><span class="token punctuation">(</span>count <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">1000</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">clearInterval</span><span class="token punctuation">(</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 正确：函数式更新不读取外部 count</span></span>
<span class="line"><span class="token function">useEffect</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> id <span class="token operator">=</span> <span class="token function">setInterval</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">setCount</span><span class="token punctuation">(</span><span class="token parameter">c</span> <span class="token operator">=&gt;</span> c <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">1000</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">clearInterval</span><span class="token punctuation">(</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>需要读取最新值但不希望它触发 Effect 重新同步时，应先判断这段逻辑是否属于非响应式事件；可使用 ref，或在支持的 React 版本中使用 <code>useEffectEvent</code>。不能把这当作随意绕过依赖规则的手段。</p><hr><h2 id="七、strict-mode-下为什么像-执行了两次" tabindex="-1"><a class="header-anchor" href="#七、strict-mode-下为什么像-执行了两次"><span>七、Strict Mode 下为什么像“执行了两次”</span></a></h2><p><code>&amp;lt;StrictMode&amp;gt;</code> 只在<strong>开发环境</strong>增加检查，不影响生产构建。常见行为包括：</p><ul><li>额外调用组件函数、类 <code>constructor</code>、<code>render</code>、<code>shouldComponentUpdate</code> 等应保持纯粹的逻辑，以发现副作用；</li><li>初次挂载时额外执行一次 Effect 的 setup → cleanup，再执行真实 setup；</li><li>类组件会出现 <code>componentDidMount</code> → <code>componentWillUnmount</code> → <code>componentDidMount</code> 的检查序列；</li><li>ref callback 也会额外执行 setup/cleanup 检查。</li></ul><p>正确修复方式是让渲染保持纯粹、让 cleanup 完整撤销 setup，而不是用全局标记阻止第二次执行。</p><hr><h2 id="八、面试速记表" tabindex="-1"><a class="header-anchor" href="#八、面试速记表"><span>八、面试速记表</span></a></h2><table><thead><tr><th style="text-align:left;">阶段</th><th style="text-align:left;">类组件 API</th><th style="text-align:center;">能否产生副作用</th><th style="text-align:left;">函数组件常见方案</th></tr></thead><tbody><tr><td style="text-align:left;">挂载前</td><td style="text-align:left;"><code>constructor</code></td><td style="text-align:center;">否</td><td style="text-align:left;"><code>useState</code> / <code>useReducer</code> 惰性初始化</td></tr><tr><td style="text-align:left;">挂载/更新渲染前</td><td style="text-align:left;"><code>getDerivedStateFromProps</code></td><td style="text-align:center;">否</td><td style="text-align:left;">渲染期间派生；必要时 <code>key</code> 重置</td></tr><tr><td style="text-align:left;">渲染</td><td style="text-align:left;"><code>render</code></td><td style="text-align:center;">否</td><td style="text-align:left;">函数组件函数体</td></tr><tr><td style="text-align:left;">更新判断</td><td style="text-align:left;"><code>shouldComponentUpdate</code></td><td style="text-align:center;">否</td><td style="text-align:left;"><code>memo</code></td></tr><tr><td style="text-align:left;">DOM 更新前快照</td><td style="text-align:left;"><code>getSnapshotBeforeUpdate</code></td><td style="text-align:center;">只读 DOM</td><td style="text-align:left;">无精确 Hook 对应物</td></tr><tr><td style="text-align:left;">挂载提交后</td><td style="text-align:left;"><code>componentDidMount</code></td><td style="text-align:center;">可以</td><td style="text-align:left;"><code>useEffect</code> / <code>useLayoutEffect</code></td></tr><tr><td style="text-align:left;">更新提交后</td><td style="text-align:left;"><code>componentDidUpdate</code></td><td style="text-align:center;">可以</td><td style="text-align:left;">依赖明确的 <code>useEffect</code> / <code>useLayoutEffect</code></td></tr><tr><td style="text-align:left;">卸载前</td><td style="text-align:left;"><code>componentWillUnmount</code></td><td style="text-align:center;">只做清理</td><td style="text-align:left;">Effect cleanup</td></tr><tr><td style="text-align:left;">错误降级</td><td style="text-align:left;"><code>getDerivedStateFromError</code></td><td style="text-align:center;">否</td><td style="text-align:left;">无内置函数边界 Hook</td></tr><tr><td style="text-align:left;">错误记录</td><td style="text-align:left;"><code>componentDidCatch</code></td><td style="text-align:center;">可以</td><td style="text-align:left;">类错误边界或封装库</td></tr><tr><td style="text-align:left;">遗留、不安全</td><td style="text-align:left;">三个 <code>UNSAFE_</code> 方法</td><td style="text-align:center;">不要使用</td><td style="text-align:left;">迁移到现行 API</td></tr></tbody></table><hr><h2 id="九、常见追问" tabindex="-1"><a class="header-anchor" href="#九、常见追问"><span>九、常见追问</span></a></h2><h3 id="useeffect-fn-是否等于-componentdidmount" tabindex="-1"><a class="header-anchor" href="#useeffect-fn-是否等于-componentdidmount"><span><code>useEffect(fn, [])</code> 是否等于 <code>componentDidMount</code>？</span></a></h3><p>不严格相等。它表示无响应式依赖的 Effect：客户端挂载提交后执行 setup，卸载时 cleanup；重新挂载会再次执行，Strict Mode 开发环境还会多一次检查循环。</p><h3 id="cleanup-是否只在卸载时执行" tabindex="-1"><a class="header-anchor" href="#cleanup-是否只在卸载时执行"><span>cleanup 是否只在卸载时执行？</span></a></h3><p>不是。依赖变化时，新 setup 执行前会先运行上一轮 cleanup；卸载时再运行最后一轮 cleanup。</p><h3 id="uselayouteffect-与-useeffect-的核心区别" tabindex="-1"><a class="header-anchor" href="#uselayouteffect-与-useeffect-的核心区别"><span><code>useLayoutEffect</code> 与 <code>useEffect</code> 的核心区别？</span></a></h3><p><code>useLayoutEffect</code> 在浏览器绘制前同步执行并阻塞绘制；<code>useEffect</code> 通常允许浏览器先绘制。默认用 <code>useEffect</code>，需要测量并同步修正布局以避免闪烁时才用 <code>useLayoutEffect</code>。</p><h3 id="react-生命周期的本质是什么" tabindex="-1"><a class="header-anchor" href="#react-生命周期的本质是什么"><span>React 生命周期的本质是什么？</span></a></h3><p>类组件按组件实例的挂载、更新、卸载组织逻辑；Effect 则按“建立某个外部同步过程，以及何时清理/重建它”组织逻辑。Hooks 的重点是按关注点聚合 setup 和 cleanup，而不是逐个复刻类生命周期。</p><hr><h2 id="官方资料" tabindex="-1"><a class="header-anchor" href="#官方资料"><span>官方资料</span></a></h2><ul><li><a href="https://react.dev/reference/react/Component" target="_blank" rel="noopener noreferrer">Component（完整类组件 API）</a></li><li><a href="https://react.dev/reference/react/useEffect" target="_blank" rel="noopener noreferrer">useEffect</a></li><li><a href="https://react.dev/reference/react/useLayoutEffect" target="_blank" rel="noopener noreferrer">useLayoutEffect</a></li><li><a href="https://react.dev/reference/react/useInsertionEffect" target="_blank" rel="noopener noreferrer">useInsertionEffect</a></li><li><a href="https://react.dev/reference/react/StrictMode" target="_blank" rel="noopener noreferrer">StrictMode</a></li><li><a href="https://react.dev/reference/rules/components-and-hooks-must-be-pure" target="_blank" rel="noopener noreferrer">Components and Hooks must be pure</a></li></ul>`,204)])])}const i=s(p,[["render",l]]),d=JSON.parse('{"path":"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E9%9D%A2%E8%AF%95/%E5%85%AB%E8%82%A1/React/%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%20%E2%8C%9A%EF%B8%8F.html","title":"生命周期 ⌚️","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/前端/面试/八股/React/生命周期 ⌚️.md"}');export{i as comp,d as data};
